# Review package: 6ebf489717be8d04eceec970c9bcbe973eb23c43..0974d69

## Commits
0974d69 Add greeting function with tests

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 28 ++++++++++++++++++++++++++++
 package.json  |  5 ++++-
 3 files changed, 40 insertions(+), 1 deletion(-)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..5a9f66f
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name) {
+    return 'Hello, there!';
+  }
+  return `Hello, ${name}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..fc8b1bf
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,28 @@
+const { test } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for a valid name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet formats greeting with different names', () => {
+  assert.strictEqual(greet('Bob'), 'Hello, Bob!');
+  assert.strictEqual(greet('Charlie'), 'Hello, Charlie!');
+});
diff --git a/package.json b/package.json
index c550c1c..f26c860 100644
--- a/package.json
+++ b/package.json
@@ -1,6 +1,9 @@
 {
   "name": "drill-test-project",
   "version": "1.0.0",
   "description": "Test project for Drill scenarios",
-  "main": "src/index.js"
+  "main": "src/index.js",
+  "scripts": {
+    "test": "node --test"
+  }
 }
